import java.util.HashMap;
import java.util.Map;

public class ContadorFrecuencia {
    public static void main(String[] args) {
        String texto = "java es genial";
        HashMap<Character, Integer> frecuencias = new HashMap<>();
        for (int i = 0; i < texto.length(); i++) {
            char letra = texto.charAt(i);
            if (letra != ' ') {
                frecuencias.put(letra, frecuencias.getOrDefault(letra, 0) + 1);
            }
        }
        for (Map.Entry<Character, Integer> entry : frecuencias.entrySet()) {
            System.out.println(entry.getKey() + " = " + entry.getValue());
        }
    }
}

