import java.util.ArrayList;
import java.util.HashMap;

public class AgruparPorCategoria {
    public static void main(String[] args) {
        HashMap<String, String> productos = new HashMap<>();
        productos.put("Laptop", "Electrónica");
        productos.put("Camisa", "Ropa");
        productos.put("Mouse", "Electrónica");
        productos.put("Pantalón", "Ropa");
        productos.put("Auriculares", "Electrónica");
        productos.put("Zapatillas", "Calzado");
        productos.put("Sneakers", "Calzado");

        HashMap<String, ArrayList<String>> agrupados = new HashMap<>();
        for (HashMap.Entry<String, String> entry : productos.entrySet()) {
            String categoria = entry.getValue();
            String producto = entry.getKey();
            if (!agrupados.containsKey(categoria)) {
                agrupados.put(categoria, new ArrayList<>());
            }
            agrupados.get(categoria).add(producto);
        }
        for (String categoria : agrupados.keySet()) {
            System.out.println(categoria + ": " + agrupados.get(categoria));
        }
    }
}
